"use client";

import { type KeyboardEvent, useEffect, useId, useState } from "react";

import { SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import {
  ACTIONS,
  type ActionId,
  type DocSentence,
  SENTENCES,
} from "./ai-inline-edit/data";
import { EditPanel, type PanelPhase } from "./ai-inline-edit/edit-panel";
import { GhostLine } from "./ai-inline-edit/ghost-line";
import { type Decision, SentenceView } from "./ai-inline-edit/sentence-view";
import { RedoIcon, UndoIcon } from "./icons";
import { Initials } from "./parts/initials";
import { useTicker } from "./lib/use-ticker";
import { countAllWords, revealParts } from "./lib/words";

// Enough ticks for the longest rewrite of the whole document at two words a tick.
const LIMIT = Math.ceil(
  Math.max(
    ...ACTIONS.map((action) =>
      countAllWords(SENTENCES.map((sentence) => sentence.rewrites[action.id])),
    ),
  ) / 2,
);

/** The sentence index a DOM node sits in, read from the nearest `data-index`. */
function indexOf(node: Node | null): number | null {
  const element = node instanceof Element ? node : node?.parentElement;
  const value = element?.closest("[data-index]")?.getAttribute("data-index");
  return value ? Number(value) : null;
}

/**
 * A document with an assistant inside. Select sentences, or leave the caret
 * in one, and press Mod K: a prompt opens under the text, the rewrite streams
 * in as a change, and each change can be accepted or rejected. A new sentence
 * gets ghost text that Tab accepts.
 */
export function AiInlineEdit({ className }: { className?: string }) {
  const [doc, setDoc] = useState<DocSentence[]>(SENTENCES);
  const [past, setPast] = useState<DocSentence[][]>([]);
  const [future, setFuture] = useState<DocSentence[][]>([]);
  const [caret, setCaret] = useState(1);
  const [anchor, setAnchor] = useState<number | null>(null);
  const [focused, setFocused] = useState(false);
  const [phase, setPhase] = useState<PanelPhase | null>(null);
  const [target, setTarget] = useState<[number, number]>([0, 0]);
  const [action, setAction] = useState<ActionId>("clearer");
  const [decisions, setDecisions] = useState<Partial<Record<string, Decision>>>(
    {},
  );
  const [accepted, setAccepted] = useState(0);
  const [note, setNote] = useState("");
  const [saving, setSaving] = useState(false);
  const titleId = useId();
  const stream = useTicker(LIMIT, 60);

  useEffect(() => {
    if (!saving) return;
    const id = window.setTimeout(() => setSaving(false), 700);
    return () => window.clearTimeout(id);
  }, [saving]);

  const [from, to] = phase
    ? target
    : anchor === null
      ? [caret, caret]
      : [Math.min(anchor, caret), Math.max(anchor, caret)];
  const editing = doc.slice(target[0], target[1] + 1);
  const parts = editing.map((sentence) => sentence.rewrites[action]);
  const shown = revealParts(parts, stream.tick * 2);
  const view: PanelPhase | null =
    phase === "streaming" && stream.tick * 2 >= countAllWords(parts)
      ? "review"
      : phase;

  const commit = (next: DocSentence[]) => {
    setPast([...past, doc]);
    setFuture([]);
    setDoc(next);
    setSaving(true);
  };

  const undo = () => {
    const previous = past[past.length - 1];
    if (!previous) return;
    setFuture([doc, ...future]);
    setPast(past.slice(0, -1));
    setDoc(previous);
    setSaving(true);
    if (phase === "applied") setPhase(null);
  };

  const redo = () => {
    const [next, ...rest] = future;
    if (!next) return;
    setPast([...past, doc]);
    setFuture(rest);
    setDoc(next);
    setSaving(true);
  };

  const openPrompt = () => {
    setTarget([from, to]);
    setNote("");
    setPhase("prompt");
  };

  const run = (id: ActionId) => {
    setAction(id);
    setDecisions({});
    setPhase("streaming");
    stream.start();
  };

  const finish = (choices: Partial<Record<string, Decision>>) => {
    const kept = editing.filter(
      (sentence) => choices[sentence.id] === "accepted",
    );
    if (kept.length > 0) {
      commit(
        doc.map((sentence) =>
          choices[sentence.id] === "accepted"
            ? { ...sentence, text: sentence.rewrites[action] }
            : sentence,
        ),
      );
    }
    setAccepted(kept.length);
    setAnchor(null);
    setPhase("applied");
  };

  const decide = (id: string, decision: Decision) => {
    const next = { ...decisions, [id]: decision };
    setDecisions(next);
    if (editing.every((sentence) => next[sentence.id])) finish(next);
  };

  const allAs = (decision: Decision) =>
    finish(
      Object.fromEntries(editing.map((sentence) => [sentence.id, decision])),
    );

  const stop = () => {
    stream.reset();
    setNote("Stopped. Nothing changed.");
    setPhase("prompt");
  };

  const close = () => {
    stream.reset();
    setPhase(null);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
      event.preventDefault();
      openPrompt();
      return;
    }
    if (phase && phase !== "applied") return;
    const step =
      event.key === "ArrowDown" || event.key === "ArrowRight"
        ? 1
        : event.key === "ArrowUp" || event.key === "ArrowLeft"
          ? -1
          : 0;
    if (step !== 0) {
      event.preventDefault();
      setPhase(null);
      if (event.shiftKey && anchor === null) setAnchor(caret);
      if (!event.shiftKey) setAnchor(null);
      setCaret(Math.max(0, Math.min(doc.length - 1, caret + step)));
    } else if (event.key === "Escape") {
      setAnchor(null);
    }
  };

  const onPointerUp = (shift: boolean) => {
    if (phase && phase !== "applied") return;
    const selection = window.getSelection();
    const start = indexOf(selection?.anchorNode ?? null);
    const end = indexOf(selection?.focusNode ?? null);
    if (end !== null) setPhase(null);
    if (selection && !selection.isCollapsed && start !== null && end !== null) {
      setAnchor(start);
      setCaret(end);
    } else if (end !== null) {
      if (shift) setAnchor(anchor ?? caret);
      else setAnchor(null);
      setCaret(end);
    }
  };

  const paragraphs = [...new Set(doc.map((sentence) => sentence.paragraph))];
  const panelAfter = doc[to]?.paragraph ?? 0;
  const status =
    view === "review"
      ? "Rewrite ready. Review each change."
      : phase === null && anchor !== null
        ? `${to - from + 1} sentences selected`
        : phase === null
          ? `In sentence ${caret + 1} of ${doc.length}`
          : "";

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-3">
        <div className="flex min-w-0 items-center gap-3">
          <Initials name="Priya Nair" tint={0} />
          <div className="min-w-0">
            <h2 id={titleId} className="truncate text-base font-semibold">
              Late cancellation policy
            </h2>
            <p className="truncate text-xs text-muted-foreground">
              Priya Nair, Harbour Street,{" "}
              <span aria-live="polite">{saving ? "saving" : "saved"}</span>
            </p>
          </div>
        </div>
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon"
            className="size-8"
            aria-label="Undo"
            disabled={past.length === 0}
            onClick={undo}
          >
            <UndoIcon aria-hidden="true" className="size-4" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="size-8"
            aria-label="Redo"
            disabled={future.length === 0}
            onClick={redo}
          >
            <RedoIcon aria-hidden="true" className="size-4" />
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={openPrompt}
            disabled={phase !== null && phase !== "applied"}
            aria-keyshortcuts="Meta+K Control+K"
          >
            <SparklesIcon aria-hidden="true" className="size-4" />
            Rewrite
            <kbd className="hidden rounded border border-border px-1 text-xs font-normal text-muted-foreground @sm:inline">
              Ctrl K
            </kbd>
          </Button>
        </div>
      </header>

      <div className="flex flex-col gap-4 px-5 py-5">
        <div
          tabIndex={0}
          role="group"
          aria-roledescription="document"
          aria-label="Policy text. Arrows move between sentences, Shift with an arrow selects, Control K asks for a rewrite."
          onKeyDown={onKeyDown}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          onPointerUp={(event) => onPointerUp(event.shiftKey)}
          className="flex flex-col gap-4 rounded-md text-base leading-7 outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-card"
        >
          {paragraphs.map((paragraph) => (
            <div key={paragraph}>
              <p>
                {doc.map((sentence, index) =>
                  sentence.paragraph === paragraph ? (
                    <SentenceView
                      key={sentence.id}
                      index={index}
                      text={sentence.text}
                      selected={
                        phase === null
                          ? anchor !== null && index >= from && index <= to
                          : phase === "prompt" && index >= from && index <= to
                      }
                      caret={
                        focused &&
                        phase === null &&
                        anchor === null &&
                        index === caret
                      }
                      rewrite={
                        view === "streaming" || view === "review"
                          ? index >= target[0] && index <= target[1]
                            ? (shown[index - target[0]] ?? "")
                            : undefined
                          : undefined
                      }
                      streaming={view === "streaming"}
                      reviewing={view === "review"}
                      decision={decisions[sentence.id]}
                      onDecide={(decision) => decide(sentence.id, decision)}
                    />
                  ) : null,
                )}
              </p>
              {view && paragraph === panelAfter ? (
                <EditPanel
                  phase={view}
                  count={to - from + 1}
                  accepted={accepted}
                  note={note}
                  onRun={run}
                  onStop={stop}
                  onAcceptAll={() => allAs("accepted")}
                  onDiscard={() => allAs("rejected")}
                  onUndo={undo}
                  onClose={close}
                />
              ) : null}
            </div>
          ))}
        </div>
        <div className="border-t border-dashed border-border pt-3">
          <GhostLine
            onAdd={(text) =>
              commit([
                ...doc,
                {
                  id: `added-${doc.length}`,
                  paragraph: 1,
                  text,
                  rewrites: { friendlier: text, shorter: text, clearer: text },
                },
              ])
            }
          />
        </div>
      </div>
      <p role="status" className="sr-only">
        {status}
      </p>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

