/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** A quick rewrite the assistant offers. */
export type ActionId = "friendlier" | "shorter" | "clearer";

/** One sentence of the document, with what each quick action would turn it into. */
export interface DocSentence {
  id: string;
  /** The paragraph it belongs to, from 0. */
  paragraph: number;
  text: string;
  rewrites: Record<ActionId, string>;
}

/** The quick actions, in the order the prompt lists them. */
export const ACTIONS: { id: ActionId; label: string; hint: string }[] = [
  {
    id: "friendlier",
    label: "Make it friendlier",
    hint: "Warmer words, same rules",
  },
  {
    id: "shorter",
    label: "Make it shorter",
    hint: "Cut what a patient can skip",
  },
  {
    id: "clearer",
    label: "Make it clearer",
    hint: "Plain words, one idea a sentence",
  },
];

/** The sample policy, sentence by sentence. */
export const SENTENCES: DocSentence[] = [
  {
    id: "s1",
    paragraph: 0,
    text: "Patients who cancel less than 24 hours before their visit will be charged a fee of $40.",
    rewrites: {
      friendlier:
        "If you need to cancel within 24 hours of your visit, we ask for a $40 fee.",
      shorter: "Cancelling within 24 hours costs $40.",
      clearer:
        "If you cancel less than 24 hours before your visit, you pay a $40 fee.",
    },
  },
  {
    id: "s2",
    paragraph: 0,
    text: "This fee is non-negotiable and applies in all circumstances whatsoever.",
    rewrites: {
      friendlier: "This helps us offer the slot to another patient.",
      shorter: "The fee always applies.",
      clearer: "The fee applies every time, except in the cases below.",
    },
  },
  {
    id: "s3",
    paragraph: 0,
    text: "Staff should inform the patient of the charge at the time of the cancellation.",
    rewrites: {
      friendlier:
        "Our front desk will let you know about the fee when you call.",
      shorter: "Staff mention the fee when you cancel.",
      clearer: "When you cancel, the front desk tells you about the fee.",
    },
  },
  {
    id: "s4",
    paragraph: 1,
    text: "If a patient fails to attend without notice, the full cost of the visit will be billed.",
    rewrites: {
      friendlier:
        "If you miss a visit without telling us, we will need to charge for the full visit.",
      shorter: "A missed visit is billed in full.",
      clearer:
        "If you miss a visit and do not tell us, you pay for the whole visit.",
    },
  },
  {
    id: "s5",
    paragraph: 1,
    text: "Repeated non-attendance may result in the patient being removed from the clinic's list.",
    rewrites: {
      friendlier:
        "If this happens often, we may talk with you about whether our clinic is the right fit.",
      shorter: "Missing many visits can end your place at the clinic.",
      clearer: "If you miss visits often, the clinic may stop booking you.",
    },
  },
  {
    id: "s6",
    paragraph: 1,
    text: "Exceptions can be made by the practice manager in cases of illness or emergency.",
    rewrites: {
      friendlier:
        "If you are ill or something urgent comes up, just tell us and we will waive the fee.",
      shorter: "Illness and emergencies are exempt.",
      clearer:
        "The practice manager can drop the fee if you are ill or have an emergency.",
    },
  },
];

/** Sentences the assistant can finish while a person types a new one. */
export const SUGGESTIONS = [
  "You can cancel or move a visit online at any time from the link in your reminder text.",
  "We will always try to offer your slot to someone on the waitlist first.",
  "Please call the front desk if you are running more than 10 minutes late.",
];

"use client";

import { motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import {
  CheckIcon,
  SparklesIcon,
  XIcon,
} from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { StopIcon, UndoIcon } from "../icons";
import { ACTIONS, type ActionId } from "./data";

/** The stages the floating layer moves through. */
export type PanelPhase = "prompt" | "streaming" | "review" | "applied";

/** Props for the floating edit layer. */
export interface EditPanelProps {
  phase: PanelPhase;
  /** How many sentences the edit covers. */
  count: number;
  /** How many of the changes have been accepted, for the receipt. */
  accepted: number;
  /** A note under the prompt, such as why the last run stopped. */
  note: string;
  onRun: (action: ActionId) => void;
  onStop: () => void;
  onAcceptAll: () => void;
  onDiscard: () => void;
  onUndo: () => void;
  onClose: () => void;
}

/** The quick action a typed request most likely means. */
function actionFor(text: string): ActionId {
  const lower = text.toLowerCase();
  if (/(short|cut|brief|trim)/.test(lower)) return "shorter";
  if (/(friend|warm|kind|soft|polite)/.test(lower)) return "friendlier";
  return "clearer";
}

/**
 * One floating layer that carries the whole edit and morphs its size from
 * stage to stage: the prompt with quick actions, a status bar with Stop, the
 * review bar, then the receipt. In the prompt, arrows move through the quick
 * actions and Enter runs one; Escape closes.
 */
export function EditPanel({
  phase,
  count,
  accepted,
  note,
  onRun,
  onStop,
  onAcceptAll,
  onDiscard,
  onUndo,
  onClose,
}: EditPanelProps) {
  const reduceMotion = useReducedMotion();
  const [text, setText] = useState("");
  const [active, setActive] = useState(0);
  const inputRef = useRef<HTMLInputElement>(null);
  const listId = useId();
  const what = count === 1 ? "1 sentence" : `${count} sentences`;

  useEffect(() => {
    if (phase === "prompt") inputRef.current?.focus();
  }, [phase]);

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      setActive(
        (active + (event.key === "ArrowDown" ? 1 : -1) + ACTIONS.length) %
          ACTIONS.length,
      );
    } else if (event.key === "Enter") {
      event.preventDefault();
      onRun(text.trim() ? actionFor(text) : (ACTIONS[active]?.id ?? "clearer"));
    } else if (event.key === "Escape") {
      event.preventDefault();
      onClose();
    }
  };

  return (
    <motion.div
      layout={!reduceMotion}
      transition={{ type: "spring", stiffness: 420, damping: 41, mass: 1 }}
      role="dialog"
      aria-label="Edit with the assistant"
      className="my-2 overflow-hidden rounded-xl border border-border bg-popover text-popover-foreground shadow-lg backdrop-blur-md"
    >
      {phase === "prompt" ? (
        <div className="flex flex-col">
          <div className="flex items-center gap-2 border-b border-border px-3 py-2">
            <SparklesIcon
              aria-hidden="true"
              className="size-4 shrink-0 text-chart-4"
            />
            <Input
              ref={inputRef}
              value={text}
              onChange={(event) => setText(event.target.value)}
              onKeyDown={onKeyDown}
              role="combobox"
              aria-expanded="true"
              aria-controls={listId}
              aria-activedescendant={
                text.trim() ? undefined : `${listId}-${active}`
              }
              aria-label={`Ask for a change to ${what}`}
              placeholder={`Ask for a change to ${what}`}
              className="h-8 min-w-0 flex-1"
            />
            <Button
              variant="ghost"
              size="icon"
              className="size-7"
              aria-label="Close"
              onClick={onClose}
            >
              <XIcon aria-hidden="true" className="size-3.5" />
            </Button>
          </div>
          <ul
            id={listId}
            role="listbox"
            aria-label="Quick actions"
            className="flex flex-col p-1"
          >
            {ACTIONS.map((action, index) => (
              <li
                key={action.id}
                id={`${listId}-${index}`}
                role="option"
                aria-selected={index === active && !text.trim()}
                onPointerDown={(event) => event.preventDefault()}
                onPointerMove={() => setActive(index)}
                onClick={() => onRun(action.id)}
                className={cn(
                  "flex min-h-10 cursor-pointer items-center justify-between gap-3 rounded-lg px-2.5 text-sm",
                  index === active && !text.trim() ? "bg-muted" : undefined,
                )}
              >
                <span>{action.label}</span>
                <span className="hidden text-xs text-muted-foreground @sm:inline">
                  {action.hint}
                </span>
              </li>
            ))}
          </ul>
          {note ? (
            <p className="border-t border-border px-3 py-2 text-xs text-muted-foreground">
              {note}
            </p>
          ) : null}
        </div>
      ) : null}

      {phase === "streaming" ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2">
          <span className="flex items-center gap-2 text-sm text-muted-foreground">
            <span
              aria-hidden="true"
              className="size-2 rounded-full bg-chart-4 motion-safe:animate-pulse"
            />
            Rewriting {what}
          </span>
          <Button variant="outline" size="sm" onClick={onStop}>
            <StopIcon aria-hidden="true" />
            Stop
          </Button>
        </div>
      ) : null}

      {phase === "review" ? (
        <div className="flex flex-wrap items-center justify-between gap-2 px-3 py-2">
          <span className="text-sm text-muted-foreground">
            Accept or reject each change, or all at once
          </span>
          <span className="flex gap-2">
            <Button variant="outline" size="sm" onClick={onDiscard}>
              <XIcon aria-hidden="true" className="size-3.5" />
              Discard
            </Button>
            <Button size="sm" onClick={onAcceptAll}>
              <CheckIcon aria-hidden="true" className="size-3.5" />
              Accept all
            </Button>
          </span>
        </div>
      ) : null}

      {phase === "applied" ? (
        <div className="flex items-center justify-between gap-3 px-3 py-2">
          <span className="flex items-center gap-2 text-sm">
            <CheckIcon
              aria-hidden="true"
              className="size-4 text-marketing-green-ink"
            />
            {accepted === 0
              ? "No changes kept"
              : `${accepted === 1 ? "1 sentence" : `${accepted} sentences`} rewritten`}
          </span>
          <span className="flex gap-1">
            {accepted > 0 ? (
              <Button variant="ghost" size="sm" onClick={onUndo}>
                <UndoIcon aria-hidden="true" className="size-3.5" />
                Undo
              </Button>
            ) : null}
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              aria-label="Close"
              onClick={onClose}
            >
              <XIcon aria-hidden="true" className="size-3.5" />
            </Button>
          </span>
        </div>
      ) : null}
    </motion.div>
  );
}

