"use client";

import { type KeyboardEvent, useId, useState } from "react";

import { Input } from "@/components/ui/input";

import { SUGGESTIONS } from "./data";

/** Props for the line that adds a sentence. */
export interface GhostLineProps {
  onAdd: (text: string) => void;
}

/**
 * A line for typing a new sentence. Once a few letters match a suggestion,
 * the rest shows as faded ghost text: Tab accepts it, Enter adds the sentence.
 * With no ghost text, Tab moves on as usual.
 */
export function GhostLine({ onAdd }: GhostLineProps) {
  const [text, setText] = useState("");
  const hintId = useId();
  const match =
    text.trim().length >= 3
      ? SUGGESTIONS.find((item) =>
          item.toLowerCase().startsWith(text.toLowerCase()),
        )
      : undefined;
  const ghost = match ? match.slice(text.length) : "";

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "Tab" && ghost && !event.shiftKey) {
      event.preventDefault();
      setText(text + ghost);
    } else if (event.key === "Enter" && text.trim()) {
      event.preventDefault();
      onAdd(text.trim());
      setText("");
    } else if (event.key === "Escape" && ghost) {
      setText(text.trimEnd());
    }
  };

  return (
    <div className="relative">
      {/* The ghost sits on top of the field and copies its border, padding and
          type size, so the suggestion starts exactly where the typed text ends. */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 z-10 flex items-center overflow-hidden border border-transparent px-3 text-base whitespace-pre md:text-sm"
      >
        <span className="invisible">{text}</span>
        <span className="text-muted-foreground/70">{ghost}</span>
      </div>
      <Input
        value={text}
        onChange={(event) => setText(event.target.value)}
        onKeyDown={onKeyDown}
        aria-label="Add a sentence"
        aria-describedby={hintId}
        placeholder="Start a new sentence, for example: Please call"
      />
      <span id={hintId} role="status" className="sr-only">
        {ghost ? `Suggestion: ${match}. Press Tab to accept.` : ""}
      </span>
    </div>
  );
}

import { CheckIcon, XIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
