/** What a person decided about one change. */
export type Decision = "accepted" | "rejected";

/** Props for one sentence of the document. */
export interface SentenceViewProps {
  index: number;
  text: string;
  /** Lit as part of the selection. */
  selected: boolean;
  /** The sentence the caret is in, shown only while the document has focus. */
  caret: boolean;
  /** The rewrite streamed so far. Undefined when the sentence is not being edited. */
  rewrite?: string;
  streaming: boolean;
  /** Set once the rewrite is complete and waiting for a decision. */
  reviewing: boolean;
  decision?: Decision;
  onDecide: (decision: Decision) => void;
}

/**
 * One sentence: plain, selected, or shown as a change with the old words
 * struck through and the new words marked as inserted. A change under review
 * carries its own accept and reject buttons.
 */
export function SentenceView({
  index,
  text,
  selected,
  caret,
  rewrite,
  streaming,
  reviewing,
  decision,
  onDecide,
}: SentenceViewProps) {
  if (rewrite === undefined) {
    return (
      <span
        data-index={index}
        className={cn(
          "rounded-sm box-decoration-clone",
          selected
            ? "bg-marketing-blue-surface text-marketing-blue-ink"
            : caret
              ? "underline decoration-chart-1 decoration-2 underline-offset-4"
              : undefined,
        )}
      >
        {text}{" "}
      </span>
    );
  }

  return (
    <span data-index={index}>
      {decision !== "accepted" ? (
        <del
          className={cn(
            "box-decoration-clone",
            decision === "rejected"
              ? "no-underline"
              : "text-marketing-orange-ink decoration-marketing-orange-ink/70",
          )}
        >
          {decision === "rejected" ? (
            text
          ) : (
            <span className="line-through">{text}</span>
          )}
        </del>
      ) : null}
      {decision !== "rejected" ? (
        <>
          {decision === undefined ? " " : null}
          <ins className="rounded-sm bg-marketing-green-surface px-0.5 text-marketing-green-ink no-underline box-decoration-clone">
            {rewrite}
            {streaming ? (
              <span
                aria-hidden="true"
                className="ml-0.5 inline-block h-4 w-0.5 translate-y-0.5 bg-chart-4 motion-safe:animate-pulse"
              />
            ) : null}
          </ins>
        </>
      ) : null}
      {reviewing && decision === undefined ? (
        <span className="ml-1 inline-flex gap-0.5 align-middle">
          <Button
            variant="outline"
            size="icon"
            className="size-6"
            aria-label={`Accept change ${index + 1}`}
            onClick={() => onDecide("accepted")}
          >
            <CheckIcon aria-hidden="true" className="size-3" />
          </Button>
          <Button
            variant="outline"
            size="icon"
            className="size-6"
            aria-label={`Reject change ${index + 1}`}
            onClick={() => onDecide("rejected")}
          >
            <XIcon aria-hidden="true" className="size-3" />
          </Button>
        </span>
      ) : null}{" "}
    </span>
  );
}

